    visualNodes: [{ title: 'Client request', detail: 'Identity and route determine policy' }, { title: 'Limiter', detail: 'Check and update allowance atomically' }, { title: 'Allowed', detail: 'Continue to the protected service' }, { title: 'Rejected', detail: 'Return 429 and retry guidance' }, { title: 'Policy state', detail: 'Local or shared counters/tokens' }], visualNote: 'A distributed implementation may place state in a shared store or use local approximations. The choice changes consistency, latency, and failure behavior.',
    visualLanes: [{ label: 'Allowance available', nodes: [{ title: 'Request', detail: 'Identify client and route' }, { title: 'Consume allowance', detail: 'Check policy state atomically' }, { title: 'Continue', detail: 'Forward to protected service' }] }, { label: 'Limit reached', nodes: [{ title: 'Request', detail: 'Identify client and route' }, { title: 'No allowance', detail: 'Policy state denies request' }, { title: 'Return 429', detail: 'Include retry guidance if known' }] }],
    steps: [{ title: 'Define the policy', what: 'Choose identity, limit, interval, burst allowance, and exceptions.', why: 'A numeric limit is meaningless without knowing who and what it applies to.' }, { title: 'Choose an algorithm', what: 'Select fixed window, sliding window, token bucket, or leaky bucket.', why: 'Algorithms differ in boundary bursts, smoothness, and state needs.' }, { title: 'Make the decision', what: 'Check and update limiter state atomically or define an acceptable approximation.', why: 'Concurrent requests must not all consume the same remaining allowance.' }, { title: 'Respond clearly', what: 'Allow work or return 429 with retry information where available.', why: 'Clients need a useful and predictable recovery signal.' }, { title: 'Plan for failure', what: 'Decide whether dependency failure is fail-open, fail-closed, or limited locally.', why: 'The choice balances protecting the service against availability.' }],
    realWorldExample: 'A public API may allow a burst of 20 requests and refill one token each second for each API key. The gateway checks and consumes a token before calling the application. When none remain, it returns 429 and a retry hint. A separate service-wide emergency limit can protect capacity even if individual clients stay within their quotas.',
    deepDive: ['Fixed windows are simple but can allow nearly twice the limit around a window boundary.', 'Sliding logs are accurate but store request timestamps; sliding counters approximate a rolling window with less state.', 'Token bucket allows bursts up to bucket capacity while controlling average rate; leaky bucket smooths outgoing work.', 'In distributed deployments, atomic increments or scripts can coordinate state, but network latency, hot keys, and store availability matter.', 'Use a monotonic time source where possible and define behavior for clock differences and expiration.'],
